import csv

# Load all day1+day2+employee names to exclude
used = set()
import glob as g, os

for f in g.glob('day1/*.tsv') + g.glob('day2/*.tsv'):
    with open(f) as fh:
        reader = csv.reader(fh, delimiter='\t')
        next(reader)
        for row in reader:
            if row: used.add(row[0].strip())

for f in os.listdir('../employee_sheets'):
    if f.startswith('employee_') and f.endswith('.tsv'):
        with open(os.path.join('../employee_sheets', f)) as fh:
            reader = csv.reader(fh, delimiter='\t')
            next(reader)
            for row in reader:
                if row: used.add(row[0].strip())

